//! The finishing of generated files: the header line and the formatting their extension selects.

use seampact_target::GeneratedFile;

use crate::not_ported::not_ported_yet;
use crate::{FilesOutcome, WriterError};

/// What the header of a generated file names.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct HeaderSource<'header> {
    /// The seampact version that generated the file.
    pub version: &'header str,
    /// The short id of the target.
    pub short_id: &'header str,
    /// The api the file was generated from.
    pub api_id: &'header str,
}

/// The one line every generated file with comment syntax starts with, without the comment marker.
#[must_use]
pub fn generated_header(source: &HeaderSource<'_>) -> String {
    format!(
        "Generated by seampact {} ({}) from api \"{}\". Do not edit.",
        source.version, source.short_id, source.api_id
    )
}

/// Adds the header and formats each file as its extension selects; a file of another extension,
/// one the formatter cannot parse or a header field that is unsafe is refused by name.
///
/// # Errors
///
/// [`WriterError::NotPortedYet`] until the function is ported.
pub fn finish_files(
    _files: &[GeneratedFile],
    _header: &HeaderSource<'_>,
) -> Result<FilesOutcome, WriterError> {
    Err(not_ported_yet("finishFiles"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_header_names_the_version_the_short_id_and_the_api() {
        let header = generated_header(&HeaderSource {
            version: "2.0.0",
            short_id: "probe-server",
            api_id: "tasks",
        });

        assert_eq!(
            header,
            "Generated by seampact 2.0.0 (probe-server) from api \"tasks\". Do not edit."
        );
    }
}
